import {mapGetters} from "vuex";
import {getDictList} from "@/api/dict";
import xtTreeLzaySelect from "@/components/xtTreeLzaySelect/index.vue";
import {getDeptList} from "@/api/system/dept";

export default {
  components:{xtTreeLzaySelect},
  data() {
    return {
      tableLoading: false, //表格加载
      tableHeight: undefined,
      dataList:[],
      receiveUnitList:[],
      oprtDeptList: [],
      searchForm: {
        current: 1,
        size: 20
      },
      total: 0,
      form: {},
      query: {},
      loading: true,
      selectionList: [],
    };
  },
  computed: {
    ...mapGetters(["permission"]),
    permissionList() {
      return {
        addBtn: this.vaildData(this.permission.warehouse_add, false),
        viewBtn: this.vaildData(this.permission.warehouse_view, false),
        delBtn: this.vaildData(this.permission.warehouse_delete, false),
        editBtn: this.vaildData(this.permission.warehouse_edit, false)
      };
    },
    ids() {
      let ids = [];
      this.selectionList.forEach(ele => {
        ids.push(ele.id);
      });
      return ids.join(",");
    }
  },
  mounted() {
    // 获得部门树
    this.getDeptList()
    // 设置页面元素高度
    this.setPageContentHeight()
    //加载所属单位
    this.getDictList("oprtDept");
  },
  created() {
    getList(this.searchForm).then(res=>{
      this.dataList = res.data.records
    })
  },
  methods: {
    getEntityReceiveUnit(val) {
      //选择所属单位
      this.searchForm.ownerUnit = val.fullName
      this.searchForm.ownerUnitId= val.id
      this.$refs.searchForm.$forceUpdate()
      this.$forceUpdate()
    },
    async getDeptList() {
      //加载部门数据
      await getDeptList().then(res => {
        this.receiveUnitList = res.data
      })
    },
    // eslint-disable-next-line no-unused-vars
    changeStatus(row,index){
      if (row.warehouseStatus=='0'){
        return "停用"
      }else if (row.warehouseStatus=='1'){
        return "启用"
      }
    },
    handleDel(){
      let selectList = this.$refs.dataTable.selection
      if (selectList.length == 0) {
        this.$message({
          type: 'warning',
          message: '请选择要删除的数据！'
        });
        return
      }
      this.$confirm('确定删除?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(() => {
        if (selectList != null && selectList.length > 0) {
          let ids = this.getIds(selectList);
          remove(ids).then(() => {
            this.$message({
              type: 'success',
              message: '删除成功！'
            });
            this.$emit('delNode', selectList)
            this.getList()
          })
        } else {
          this.$message({
            type: 'warning',
            message: '请选择要删除的数据！'
          });
        }

      })
    },
    //获取id串
    getIds(list) {
      let idList = [];
      list.forEach(ele => {
        idList.push(ele.id);
      });
      return idList.join(",");
    },
    handleEdit(row){
      this.showType = '修改'
      this.$router.push({
        path: '/detailRoute',
        query: {
          componentName: 'warehouseForm',
          routerTitle: '仓库表单',
          showType: this.showType,
          id:row.id
        }
      });
    },
    handleAdd(){
      this.showType = '新增'
      this.$router.push({
        path: '/detailRoute',
        query: {
          componentName: 'warehouseForm',
          routerTitle: '仓库表单',
          showType: this.showType
        }
      });
    },
    handleView(row){
      this.showType = '查看'
      this.$router.push({
        path: '/detailRoute',
        query: {
          componentName: 'warehouseForm',
          routerTitle: '仓库表单',
          showType: this.showType,
          id:row.id
        }
      });
    },
    handleReset(){
      this.searchForm = {
        current: 1,
        size: 20,
      }
      this.getList()
    },
    getList(){
      this.tableLoading = true
      getList(this.searchForm).then(res=>{
        this.dataList = res.data.records
        this.total = res.data.total
        this.tableLoading = false
      })
      this.changeStatus()
    },
    handleQuery(){
      this.searchForm.current = 1
      this.getList()
    },
    // 设置表格高度
    setTableHeight() {
      let bodyBox = document.getElementsByClassName('page_body')
      this.tableHeight = (bodyBox[0].offsetHeight - 97) + 'px'
    },
    getDictList(code){
      //加载字典
      getDictList(code).then(res => {
        if(code==='oprtDept'){
          this.oprtDeptList = res.data;
        }
      });
    },
    showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code != '') {
        let items = dictList.filter(item => item.dictKey == code);
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    },
    handleDeleteOne(id){
      //删除按钮
      let ids =  id;
      this.handleDeleteConfirm(ids);
      this.selectionList.filter(item => item!=id);
    },
    handleDeleteConfirm(ids) {
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。","确定将选择数据删除?", {
        confirmButtonText: "确定删除",
        cancelButtonText: "取消",
        type: "warning"
      })
        .then(() => {
          return remove0(ids);
        })
        .then(() => {
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          this.getList()
        });
    },
    rowSave(row, done, loading) {
      add(row).then(() => {
        done();
        this.onLoad(this.page);
        this.$message({
          type: "success",
          message: "操作成功!"
        });
      }, error => {
        //  
        loading();
      });
    },
    rowUpdate(row, index, done, loading) {
      update(row).then(() => {
        done();
        this.onLoad(this.page);
        this.$message({
          type: "success",
          message: "操作成功!"
        });
      }, error => {
        //  
        loading();
      });
    },
    rowDel(row) {
      this.$confirm("确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      })
        .then(() => {
          return remove(row.id);
        })
        .then(() => {
          this.onLoad(this.page);
          this.$message({
            type: "success",
            message: "操作成功!"
          });
        });
    },
    handleDelete() {
      if (this.selectionList.length === 0) {
        this.$message.warning("请选择至少一条数据");
        return;
      }
      this.$confirm("确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      })
        .then(() => {
          return remove(this.ids);
        })
        .then(() => {
          this.onLoad(this.page);
          this.$message({
            type: "success",
            message: "操作成功!"
          });
          this.$refs.crud.toggleSelection();
        });
    },
    beforeOpen(done, type) {
      if (["edit", "view"].includes(type)) {
        getDetail(this.form.id).then(res => {
          this.form = res.data;
        });
      }
      done();
    },
    searchReset() {
      this.query = {};
      this.onLoad(this.page);
    },
    searchChange(params, done) {
      this.query = params;
      this.page.currentPage = 1;
      this.onLoad(this.page, params);
      done();
    },
    selectionChange(list) {
      this.selectionList = list;
    },
    selectionClear() {
      this.selectionList = [];
      this.$refs.crud.toggleSelection();
    },
    currentChange(currentPage){
      this.page.currentPage = currentPage;
    },
    sizeChange(pageSize){
      this.page.pageSize = pageSize;
    },
  }
};
